; ============================================================
; NTC program - generated by NTC BASIC (VB style BASIC to NTC)
; platform: neogeo (SNK Neo Geo (68000)), starts in turbo mode
; ============================================================

			org 0

;## ntc_md_vectors ntc_ng_boot
; (the 68k backend requires this section be named ntc_md_vectors - it's the
;  generic "68k vectors + header + start" slot, named after the first 68k target)
; The 68000 vector table at 0, then the Neo Geo cart header / BIOS jump table.
; ;!!NG the real Neo Geo P-ROM header (the "NEO-GEO" marker, the USER and
; interrupt jump entries, the security/soft-DIP area) goes here - stubbed.
			dc.l $00100000          ; initial SSP (top of 68k work RAM) ;!!NG
			dc.l ntc_ng_boot        ; reset PC
			ds.l 62, 0              ; the rest of the 68000 vectors (IRQ, traps) ;!!NG wire VBlank
; ---- the cart header would follow here (ds to $100, the NEO-GEO marker ...) ;!!NG

NTC_TERM	equ 0		; Option Terminal: 0 none, 1 VT52, 2 ANSI (CP/M)
NTC_STRMAX	equ 40		; the longest string (library buffers, temps)
NTC_MEMBANKS	equ 64		; Option Memory: the most 64K banks the Memory class looks for
NTC_ROMENABLE	equ 0		; Option RomEnable (cpcfw, cpcmin): the start code starts the ROMs
NTC_ROMLIB	equ 0		; 1 = the library is the keyword ROM (Library: ROM; ntcRomAsm builds it)
NTC_WINHOLE	equ 0		; 1 = the program is built round an Option Reserve range over the window #4000-#7FFF
NTC_BUFSIZE	equ 2048		; the library's buffer (ntc_buf: FileSystem, Memory.Copy): Option Buffer
NTC_CPMGFX	equ 0		; 1 = CP/M: Graphics draws on an Amstrad CPC's screen (2.2: #C000, Plus: block 1 from common memory)
NTC_RS		macro			; the real stack: the thread position kept in ntc_ip
			move.l sp, ntc_ip
			movea.l ntc_csp, sp
			endm
NTC_TS		macro			; back to the thread
			movea.l ntc_ip, sp
			endm

ntc_start:
			move.l sp, ntc_csp		; the real stack (the library's jsr calls)
			lea main_thread, sp
			rts

; ============================================================
; Main Thread
; ============================================================

main_thread:

			; Main.bas 4: c.Reset
			dc.l p_counter_reset_c

			; Main.bas 5: c.Add 5
			dc.l p_counter_add_c, lit_5

			; Main.bas 6: c.Add 7
			dc.l p_counter_add_c, lit_7

			; Main.bas 7: Print "count "; c.Count; " total "; c.Total
			dc.l p_counter_count_get_c
			dc.l kw_printstrvar, str0
			dc.l kw_printint, var_counter_count_get_count
			dc.l p_counter_total_get_c
			dc.l kw_printstrvar, str1
			dc.l kw_printint, var_counter_total_get_total
			dc.l kw_printnl

			; Main.bas 8: c.Limit = 3
			dc.l p_counter_limit_let_c, lit_3

			; Main.bas 9: Print "limit "; c.Limit
			dc.l p_counter_limit_get_c
			dc.l kw_printstrvar, str2
			dc.l kw_printint, var_counter_limit_get_limit
			dc.l kw_printnl

			; Main.bas 10: r = Counter.Total
			dc.l p_counter_total_get_c
			dc.l kw_vtov, var_counter_total_get_total, var_r

			; Main.bas 11: Print "direct "; r
			dc.l kw_printstrvar, str3
			dc.l kw_printint, var_r
			dc.l kw_printnl

			; Main.bas 12: Print c.Describe("x")
			dc.l p_counter_describe_c, str4
			dc.l kw_printstrvar, var_counter_describe_describe
			dc.l kw_printnl
			dc.l kw_printnl0
			dc.l kw_printstrvar, str5
			dc.l kw_waitkey
			dc.l kw_stop

; ============================================================
; sub reset (turbo mode)
; ============================================================

p_counter_reset:

			; Counter.cls 12: mCount = 0
			dc.l kw_ztov, var_counter_mcount

			; Counter.cls 13: mTotal = 0
			dc.l kw_ztov, var_counter_mtotal
			dc.l p_counter_reset_r

; ============================================================
; sub add (turbo mode)
; ============================================================

p_counter_add:

			; Counter.cls 17: mCount = mCount + 1
			dc.l kw_inc, var_counter_mcount

			; Counter.cls 18: mTotal = mTotal + v
			dc.l kw_add, var_counter_mtotal, var_counter_add_v, var_counter_mtotal
			dc.l p_counter_add_r

; ============================================================
; propget count (turbo mode)
; ============================================================

p_counter_count_get:

			; Counter.cls 22: Count = mCount
			dc.l kw_vtov, var_counter_mcount, var_counter_count_get_count
			dc.l p_counter_count_get_r

; ============================================================
; propget total (turbo mode)
; ============================================================

p_counter_total_get:

			; Counter.cls 26: Total = mTotal
			dc.l kw_vtov, var_counter_mtotal, var_counter_total_get_total
			dc.l p_counter_total_get_r

; ============================================================
; proplet limit (turbo mode)
; ============================================================

p_counter_limit_let:

			; Counter.cls 30: mLimit = v
			dc.l kw_vtov, var_counter_limit_let_v, var_counter_mlimit
			dc.l p_counter_limit_let_r

; ============================================================
; propget limit (turbo mode)
; ============================================================

p_counter_limit_get:

			; Counter.cls 34: Limit = mLimit
			dc.l kw_vtov, var_counter_mlimit, var_counter_limit_get_limit
			dc.l p_counter_limit_get_r

; ============================================================
; function describe (turbo mode)
; ============================================================

p_counter_describe:

			; Counter.cls 38: Describe = s & "=" & mTotal
			dc.l kw_strcpy, stmp0, var_counter_describe_s
			dc.l kw_strcat, stmp0, str6
			dc.l kw_strcstr, stmp1, var_counter_mtotal
			dc.l kw_strcpy, var_counter_describe_describe, stmp0
			dc.l kw_strcat, var_counter_describe_describe, stmp1
			dc.l p_counter_describe_r

; ============================================================
; Jump stubs (code, ROMable)
;   label_go: GOTO label
;   label_gs: GOSUB label, return point -> label_rs (RAM)
;   label_rt: RETURN from label
;   p_name_c: call a procedure, p_name_r: end of it
;   turbo mode ends with ret, normal mode with jp ntc_xn
; ============================================================


p_counter_reset_c:		; call reset
			move.l sp, p_counter_reset_rs
			lea p_counter_reset, sp
			rts
p_counter_reset_r:		; end of reset
			movea.l p_counter_reset_rs, sp
			rts
p_counter_add_c:		; call add
			movea.l (sp)+, a0		; v
			move.w (a0), var_counter_add_v
			move.l sp, p_counter_add_rs
			lea p_counter_add, sp
			rts
p_counter_add_r:		; end of add
			movea.l p_counter_add_rs, sp
			rts
p_counter_count_get_c:		; call count
			clr.w var_counter_count_get_count
			move.l sp, p_counter_count_get_rs
			lea p_counter_count_get, sp
			rts
p_counter_count_get_r:		; end of count
			movea.l p_counter_count_get_rs, sp
			rts
p_counter_total_get_c:		; call total
			clr.w var_counter_total_get_total
			move.l sp, p_counter_total_get_rs
			lea p_counter_total_get, sp
			rts
p_counter_total_get_r:		; end of total
			movea.l p_counter_total_get_rs, sp
			rts
p_counter_limit_let_c:		; call limit
			movea.l (sp)+, a0		; v
			move.w (a0), var_counter_limit_let_v
			move.l sp, p_counter_limit_let_rs
			lea p_counter_limit_let, sp
			rts
p_counter_limit_let_r:		; end of limit
			movea.l p_counter_limit_let_rs, sp
			rts
p_counter_limit_get_c:		; call limit
			clr.w var_counter_limit_get_limit
			move.l sp, p_counter_limit_get_rs
			lea p_counter_limit_get, sp
			rts
p_counter_limit_get_r:		; end of limit
			movea.l p_counter_limit_get_rs, sp
			rts
p_counter_describe_c:		; call describe
			movea.l (sp)+, a0		; s
			lea var_counter_describe_s, a1
			move.w #40, d1
			subq.w #1, d1
			bmi p_counter_describe_si0_e
p_counter_describe_si0:
			move.b (a0)+, (a1)+
			dbeq d1, p_counter_describe_si0
			beq p_counter_describe_si0_z
p_counter_describe_si0_e:
			clr.b (a1)
p_counter_describe_si0_z:
			clr.b var_counter_describe_describe
			move.l sp, p_counter_describe_rs
			lea p_counter_describe, sp
			rts
p_counter_describe_r:		; end of describe
			movea.l p_counter_describe_rs, sp
			rts

; ============================================================
; Variables
; ============================================================

; (68000: in the RAM block at the end, from $FF8000)

; numbers passed by address (read only)
			even
ntc_aptab:		dc.l 0		; AddressOf: the procedures CallAddr runs, by number
lit_5:			dc.w 5
lit_7:			dc.w 7
lit_3:			dc.w 3

; ============================================================
; Strings
; ============================================================

str0:			dc.b "count ", 0
str1:			dc.b " total ", 0
str2:			dc.b "limit ", 0
str3:			dc.b "direct ", 0
str4:			dc.b "x", 0
str5:			dc.b "Press a key", 0
str6:			dc.b "=", 0
			even

; ============================================================
; Keyword library (used)
; ============================================================

			even
;## ntc_data @shared
; ------------------------------------------------------------
; The core every program has: the thread / real stack switch
; ------------------------------------------------------------
; (NTC_RS / NTC_TS, the macros that switch to the real stack and back, are written
; by the compiler at the top of the program, before anything uses them)
ntc_next:	rts						; A6 target that continues the thread

			even
;## kw_stop ntc_data ntc_plat_exit @shared
kw_stop:
			NTC_RS
			jsr ntc_plat_exit
ntc_stop_loop:
			bra ntc_stop_loop		; a Mega Drive has nowhere to go back to

			even
;## kw_waitkey ntc_data ntc_plat_key
; kw_waitkey - wait for a key (Option PressAnyKeyOnEnd, before kw_stop)
kw_waitkey:
			NTC_RS
			jsr ntc_plat_getkey
			NTC_TS
			rts

			even
;## kw_vtov
;kw_vtov, <sourcevar>, <destvar>
kw_vtov:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.w (a0), (a1)
			rts

			even
;## kw_ztov
;kw_ztov, <destvar>
kw_ztov:
			movea.l (sp)+, a0
			clr.w (a0)
			rts

			even
;## kw_inc
kw_inc:
			movea.l (sp)+, a0
			addq.w #1, (a0)
			rts

			even
;## kw_add
;kw_add, <var1>, <var2>, <destvar>
kw_add:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.w (a0), d0
			add.w (a1), d0
			movea.l (sp)+, a0
			move.w d0, (a0)
			rts

			even
;## kw_strcpy
;kw_strcpy, <destaddr>, <srcaddr>  - cut at the destination's capacity byte
kw_strcpy:
			movea.l (sp)+, a1
			movea.l (sp)+, a0
			moveq #0, d1
			move.b -1(a1), d1
ntc_strcpy_lp:					; a0 -> a1, at most d1 chars (d1.w > 0), then the 0
			subq.w #1, d1
			bmi ntc_strcpy_cut
ntc_strcpy_l2:
			move.b (a0)+, (a1)+
			dbeq d1, ntc_strcpy_l2
			beq ntc_strcpy_e
ntc_strcpy_cut:
			clr.b (a1)
ntc_strcpy_e:
			rts

			even
;## kw_strcat
;kw_strcat, <destaddr>, <srcaddr>  - cut at the destination's capacity byte
kw_strcat:
			movea.l (sp)+, a1
			movea.l (sp)+, a0
			moveq #0, d1
			move.b -1(a1), d1
kw_sc_end:
			tst.b (a1)
			beq kw_sc_copy
			addq.l #1, a1
			subq.w #1, d1
			bgt kw_sc_end
			rts
kw_sc_copy:
			tst.w d1
			beq kw_sc_none
			subq.w #1, d1
kw_sc_lp:
			move.b (a0)+, (a1)+
			dbeq d1, kw_sc_lp
			beq kw_sc_none
			clr.b (a1)
kw_sc_none:
			rts

			even
;## ntc_printbuf ntc_data ntc_plat_screen
; print the 0 terminated text at a0, then rts (thread). On the thread.
ntc_printbuf:
			NTC_RS
			movea.l a0, a2
ntc_pb_lp:
			moveq #0, d0
			move.b (a2)+, d0
			beq ntc_pb_end
			jsr ntc_plat_putc
			bra ntc_pb_lp
ntc_pb_end:
			NTC_TS
			rts

			even
;## kw_printstrvar ntc_printbuf
;kw_printstrvar, <straddr>
kw_printstrvar:
			movea.l (sp)+, a0
			bra ntc_printbuf

			even
;## ntc_itoa ntc_data
; d0.w = signed value, a1 = buffer: the digits and a 0 (a1 ends on the 0).
; jmp (a6). Uses d0-d2, a0
ntc_itoa:
			ext.l d0
			bpl ntc_ia_pos
			move.b #'-', (a1)+
			neg.l d0
ntc_ia_pos:
			lea ntc_ia_tmp+8, a0
			clr.b -(a0)
ntc_ia_lp:
			divu.w #10, d0
			swap d0
			addi.b #'0', d0
			move.b d0, -(a0)
			clr.w d0
			swap d0
			tst.w d0
			bne ntc_ia_lp
ntc_ia_cp:
			move.b (a0)+, (a1)+
			bne ntc_ia_cp
			subq.l #1, a1
			jmp (a6)

			even
;## kw_printint ntc_printbuf ntc_itoa
;kw_printint, <var>  - signed decimal
kw_printint:
			movea.l (sp)+, a0
			move.w (a0), d0
			lea ntc_numbuf, a1
			lea kw_pi_done, a6
			bra ntc_itoa
kw_pi_done:
			lea ntc_numbuf, a0
			bra ntc_printbuf

			even
;## kw_printnl0 ntc_data ntc_plat_screen
;kw_printnl0  - new line unless the cursor is at the start of a line
kw_printnl0:
			tst.b ntc_curx
			beq kw_pn0_end
			NTC_RS
			jsr ntc_plat_newline
			NTC_TS
kw_pn0_end:
			rts

			even
;## kw_printnl ntc_data ntc_plat_screen
kw_printnl:
			NTC_RS
			jsr ntc_plat_newline
			NTC_TS
			rts

			even
;## kw_strcstr ntc_itoa
;kw_strcstr, <dest>, <nvar>  - number to text (CStr, "x" & n)
kw_strcstr:
			movea.l (sp)+, a1
			movea.l (sp)+, a0
			move.w (a0), d0
			lea ntc_next, a6
			bra ntc_itoa

			even
;## ntc_ng_boot ntc_plat_data ntc_data ntc_plat_screen
ntc_ng_boot:
			move.w #$2700, sr          ; interrupts off during setup
			move.b d0, REG_DIPSW       ; kick the watchdog (any write)     ;!!NG value
			; clear the fix layer, set up the palette and a text font in fix tiles
			jsr ntc_ng_fixclear        ; (below)
			; hand control to the thread - the compiler's start code follows;
			; it sets A7 to the thread and runs. Interrupts get re-enabled there.
			; (ntc_plat_data / screen are pulled in as deps.)
			rts

			even
;## ntc_plat_data ntc_data
ntc_curx:   dc.w 0                     ; fix-layer cursor column (0..39)
ntc_cury:   dc.w 0                     ; row (0..31)
ntc_frames: dc.w 0                     ; frame counter (ntc_plat_ticks)

			even
;## ntc_plat_screen ntc_plat_data ntc_data
; the platform routines are entered with jsr and end with rts (real stack),
; keeping d2-d7 / a2-a6 (the 68k backend's convention).

; ntc_ng_fixaddr - d1.w = the VRAM word address of (ntc_curx, ntc_cury) in the
; fix map. The fix map is column-major: addr = NG_FIXMAP + col*32 + row.  ;!!NG layout
ntc_ng_fixaddr:
			move.w ntc_curx, d1
			lsl.w #5, d1               ; col * 32
			add.w ntc_cury, d1
			add.w #NG_FIXMAP, d1
			rts

; ntc_plat_putc - d0.b = character 32..126: write it as a fix tile, advance
ntc_plat_putc:
			jsr ntc_ng_fixaddr
			move.w d1, REG_VRAMADDR
			move.w #1, REG_VRAMMOD     ; (irrelevant for a single write)
			and.w #$00FF, d0
			; fix tile word = palette<<12 | char code ;!!NG tile numbering / font must be uploaded
			move.w d0, REG_VRAMRW
			addq.w #1, ntc_curx
			cmp.w #40, ntc_curx
			blt.s ntc_pc_done
			jsr ntc_plat_newline
ntc_pc_done:
			rts

; ntc_plat_newline - CR LF: column 0, next row (scroll not done yet) ;!!NG scroll
ntc_plat_newline:
			clr.w ntc_curx
			addq.w #1, ntc_cury
			cmp.w #32, ntc_cury
			blt.s ntc_nl_done
			move.w #31, ntc_cury
ntc_nl_done:
			rts

; ntc_ng_fixclear - blank the whole fix layer (space tile)   ;!!NG space tile index
ntc_ng_fixclear:
			move.w #NG_FIXMAP, REG_VRAMADDR
			move.w #1, REG_VRAMMOD
			move.w #40*32-1, d1
ntc_fc_lp:
			move.w #$0020, REG_VRAMRW
			dbra d1, ntc_fc_lp
			clr.w ntc_curx
			clr.w ntc_cury
			rts

			even
;## ntc_plat_key ntc_plat_data ntc_data
; ntc_plat_scankey - d0.b = a key or 0. Reads P1 (active low). Maps the stick
; to the CPC cursor codes and A/B/C to "A"/"B"/"C"; Start = 13.  ;!!NG bit map
ntc_plat_scankey:
			moveq #0, d0
			move.b REG_P1CNT, d1
			not.b d1                    ; active low -> 1 = pressed
			btst #4, d1                 ; A
			beq.s ntc_sk_b
			moveq #'A', d0
			rts
ntc_sk_b:
			btst #5, d1                 ; B
			beq.s ntc_sk_start
			moveq #'B', d0
			rts
ntc_sk_start:
			move.b REG_STATUS_B, d1
			not.b d1
			btst #0, d1                 ; Start P1
			beq.s ntc_sk_none
			moveq #13, d0
ntc_sk_none:
			rts

; ntc_plat_getkey - wait for a key
ntc_plat_getkey:
			jsr ntc_plat_scankey
			tst.b d0
			beq.s ntc_plat_getkey
			rts

			even
;## ntc_plat_exit ntc_plat_data
; ntc_plat_exit - a cart can't "exit"; spin (a real build returns to the BIOS
; menu / soft-resets) ;!!NG
ntc_plat_exit:
			bra.s ntc_plat_exit


			even
ntc_romend:			; the end of the ROM: the RAM block's first image follows
			org $FF8000
ntc_ram:
; variables
var_counter_count_get_count:			dc.w 0
var_counter_total_get_total:			dc.w 0
var_counter_limit_get_limit:			dc.w 0
var_r:			dc.w 0
			dc.b 40			; capacity
var_counter_describe_describe:			ds.b 41
			even
p_counter_reset_rs:			dc.l 0
var_counter_mcount:			dc.w 0
var_counter_mtotal:			dc.w 0
p_counter_add_rs:			dc.l 0
var_counter_add_v:			dc.w 0
p_counter_count_get_rs:			dc.l 0
p_counter_total_get_rs:			dc.l 0
p_counter_limit_let_rs:			dc.l 0
var_counter_limit_let_v:			dc.w 0
var_counter_mlimit:			dc.w 0
p_counter_limit_get_rs:			dc.l 0
p_counter_describe_rs:			dc.l 0
			dc.b 40			; capacity
var_counter_describe_s:			ds.b 41
			even
			dc.b 40			; capacity
stmp0:			ds.b 41
			even
			dc.b 40			; capacity
stmp1:			ds.b 41
			even
			even
ntc_csp:	dc.l 0					; the real stack (set at start)
ntc_ip:		dc.l 0					; the thread position while on the real stack
ntc_ivar:	dc.l 0					; input / inkey / ticks: dest var
ntc_sptr:	dc.l 0					; printbuf: text pointer
ntc_numbuf:	ds.b 16					; printint / long print: digits
			even
ntc_ia_tmp:	ds.b 8
			even
ntc_ramend:
ntc_end:				; the end of the program (and of its file)
; arrays: after the program, not in its file - kw_bssinit checks they fit and clears them
ntc_bssfrom	equ ntc_end
ntc_bss		equ ntc_bssfrom
ntc_bss_size	equ 0
ntc_free	equ ntc_bss + ntc_bss_size	; the first free byte (heap, Memory tables)
ntc_memtab	equ ntc_free		; the Memory class's tables
